#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

/*
 * Reimplementation of prog34_fibonacci_memo based on reverse‑engineered
 * control flow. The program expects a single command‑line argument N.
 *
 * Behaviour:
 *   - No argument:               prints "NO_INPUT" and exits.
 *   - Argument not a pure decimal integer (or contains extra characters):
 *                                 prints "BAD_INPUT" and exits.
 *   - Negative integer:          prints "NEGATIVE" and exits.
 *   - Integer > 90:              prints "OUT_OF_RANGE" and exits.
 *   - Otherwise (0 <= N <= 90): computes the N‑th Fibonacci number
 *                                 (F(0)=0, F(1)=1) using memoisation and
 *                                 prints it as a decimal followed by a newline.
 */

/* memoisation tables – large enough for the allowed range (0..90) */
static long long memo[91];
static int computed[91];

static long long fib(int n)
{
    if (n < 0) {
        /* Should never be called for negative n in the original logic */
        return 0;
    }
    if (computed[n])
        return memo[n];
    long long result;
    if (n == 0)
        result = 0;
    else if (n == 1)
        result = 1;
    else
        result = fib(n - 1) + fib(n - 2);
    memo[n] = result;
    computed[n] = 1;
    return result;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    /* Use strtol to mimic the original 64‑bit signed conversion */
    long value = strtol(argv[1], &endptr, 10);

    /* No conversion performed */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    /* Extra characters after the number */
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (value < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (value > 90) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long result = fib((int)value);
    printf("%lld\n", result);
    return 0;
}
